// Generated by scripts/build-icon.ps1 from the same paths as the SVG and ICO.
// Edit the canonical geometry in that script, then regenerate all brand assets.
using System.Windows;
using System.Windows.Media;

namespace IconAdapt.App.Controls;

/// <summary>Forma's code-drawn mark, independent of fonts and bitmap scaling.</summary>
public sealed class BrandMark : FrameworkElement
{
    private static readonly DrawingGroup Artwork = CreateArtwork();

    public BrandMark()
    {
        SnapsToDevicePixels = true;
        UseLayoutRounding = true;
    }

    protected override Size MeasureOverride(Size availableSize) => new(28, 28);

    protected override void OnRender(DrawingContext context)
    {
        base.OnRender(context);
        double side = Math.Min(ActualWidth, ActualHeight);
        if (side <= 0) return;
        context.PushTransform(new TranslateTransform((ActualWidth - side) / 2, (ActualHeight - side) / 2));
        context.PushTransform(new ScaleTransform(side / 256, side / 256));
        context.DrawDrawing(Artwork);
        context.Pop();
        context.Pop();
    }

    private static SolidColorBrush Brush(string color)
    {
        var brush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(color));
        brush.Freeze();
        return brush;
    }

    private static DrawingGroup CreateArtwork()
    {
        var drawing = new DrawingGroup();
        drawing.Children.Add(new GeometryDrawing(Brush("#263444"), null, Geometry.Parse("M68,8 H188 Q248,8 248,68 V188 Q248,248 188,248 H68 Q8,248 8,188 V68 Q8,8 68,8 Z")));
        drawing.Children.Add(new GeometryDrawing(Brush("#91B9CF"), null, Geometry.Parse("M140,48 H180 Q208,48 208,76 V132 Q208,160 180,160 H140 Q112,160 112,132 V76 Q112,48 140,48 Z")));
        drawing.Children.Add(new GeometryDrawing(Brush("#F8F5ED"), null, Geometry.Parse("M80,88 H144 Q176,88 176,120 V176 Q176,208 144,208 H80 Q48,208 48,176 V120 Q48,88 80,88 Z")));
        drawing.Children.Add(new GeometryDrawing(Brush("#263444"), null, Geometry.Parse("M92,120 H132 Q144,120 144,132 V164 Q144,176 132,176 H92 Q80,176 80,164 V132 Q80,120 92,120 Z")));
        drawing.Freeze();
        return drawing;
    }
}
